package com.chambersfomo;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.SoundEffectID;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(ChambersFomoConfig.GROUP)
public interface ChambersFomoConfig extends Config
{
	String GROUP = "chambersfomo";

	@ConfigSection(
		name = "Loot odds",
		description = "How each rerolled layout is treated when it rolls loot",
		position = 0
	)
	String oddsSection = "odds";

	@ConfigSection(
		name = "Popup",
		description = "The phantom purple popup",
		position = 1
	)
	String popupSection = "popup";

	@ConfigSection(
		name = "Rare item popups",
		description = "Choose which rare items get the big glowing popup, sound and chat message. Unticked items still drop at their real rate and still count in your stats, but only show in the small quiet chest.",
		position = 2,
		closedByDefault = true
	)
	String rareSection = "rare";

	@ConfigItem(
		keyName = "personalPoints",
		name = "Your points",
		description = "The points you would have finished the raid with. Deathless is assumed.",
		section = oddsSection,
		position = 0
	)
	@Range(min = 0, max = 1_000_000)
	default int personalPoints()
	{
		return 30_000;
	}

	@ConfigItem(
		keyName = "teamPoints",
		name = "Team points",
		description = "The whole team's points. Leave at 0 for solo raids.",
		section = oddsSection,
		position = 1
	)
	@Range(min = 0, max = 5_000_000)
	default int teamPoints()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "challengeMode",
		name = "Challenge Mode",
		description = "Also roll the Twisted ancestral colour kit (1/75) and Metamorphic dust (1/400), as if every run were timed",
		section = oddsSection,
		position = 2
	)
	default boolean challengeMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPopup",
		name = "Show popup",
		description = "Show the glowing popup when a rerolled layout would have given a purple",
		section = popupSection,
		position = 0
	)
	default boolean showPopup()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clickToClose",
		name = "Click to close",
		description = "Close the popup as soon as you click the game. The click still goes through to the game.",
		section = popupSection,
		position = 2
	)
	default boolean clickToClose()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCommonPopup",
		name = "Common loot chest",
		description = "Briefly show the reward chest with the common loot on rerolls without a purple",
		section = popupSection,
		position = 3
	)
	default boolean showCommonPopup()
	{
		return true;
	}

	@ConfigItem(
		keyName = "commonPopupSeconds",
		name = "Common chest duration",
		description = "How long the common loot chest stays up. It never blocks clicks, and the next roll replaces it.",
		section = popupSection,
		position = 4
	)
	@Units(Units.SECONDS)
	@Range(min = 1, max = 10)
	default int commonPopupSeconds()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "popupSeconds",
		name = "Purple popup duration",
		description = "How long the purple chest stays on screen",
		section = popupSection,
		position = 5
	)
	@Units(Units.SECONDS)
	@Range(min = 3, max = 30)
	default int popupSeconds()
	{
		return 9;
	}

	@ConfigItem(
		keyName = "sound",
		name = "Sound",
		description = "The in-game sound played with the purple popup",
		section = popupSection,
		position = 6
	)
	default FomoSound sound()
	{
		return FomoSound.JACKPOT;
	}

	@ConfigItem(
		keyName = "soundVolume",
		name = "Sound volume",
		description = "Volume of the popup sound. It plays even when game sound effects are muted.",
		section = popupSection,
		position = 7
	)
	@Range(max = 100)
	@Units(Units.PERCENT)
	default int soundVolume()
	{
		return 70;
	}

	@ConfigItem(
		keyName = "showXpDrops",
		name = "Regret XP drops",
		description = "Show fake XP drops for the Regret skill when you reroll",
		position = 10
	)
	default boolean showXpDrops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat message on purple",
		description = "Post a game chat message when a rerolled layout would have given a purple",
		position = 11
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatDryRolls",
		name = "Chat message on dry rolls",
		description = "Also post the common loot when a rerolled layout would have given no purple",
		position = 12
	)
	default boolean chatDryRolls()
	{
		return false;
	}

	@ConfigItem(
		keyName = "rareTwistedBow",
		name = "Celebrate Twisted bow",
		description = "On: a Twisted bow gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. The big one. Turning this off is a cry for help.",
		section = rareSection,
		position = 0
	)
	default boolean rareTwistedBow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareKodai",
		name = "Celebrate Kodai insignia",
		description = "On: a Kodai insignia gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. The mage weapon piece.",
		section = rareSection,
		position = 1
	)
	default boolean rareKodai()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareElderMaul",
		name = "Celebrate Elder maul",
		description = "On: an Elder maul gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Big hammer, bigger regret.",
		section = rareSection,
		position = 2
	)
	default boolean rareElderMaul()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareDragonClaws",
		name = "Celebrate Dragon claws",
		description = "On: Dragon claws gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Spec, spec, gone.",
		section = rareSection,
		position = 3
	)
	default boolean rareDragonClaws()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareAncestral",
		name = "Celebrate Ancestral",
		description = "On: an Ancestral hat, robe top or robe bottom gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Hat, robe top and robe bottom.",
		section = rareSection,
		position = 4
	)
	default boolean rareAncestral()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareBulwark",
		name = "Celebrate Dinh's bulwark",
		description = "On: a Dinh's bulwark gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. For the tanks among us.",
		section = rareSection,
		position = 5
	)
	default boolean rareBulwark()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareDhcb",
		name = "Celebrate DHCB",
		description = "On: a Dragon hunter crossbow gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Dragons everywhere breathe a sigh of relief.",
		section = rareSection,
		position = 6
	)
	default boolean rareDhcb()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareBuckler",
		name = "Celebrate Twisted buckler",
		description = "On: a Twisted buckler gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. A shield made of regret.",
		section = rareSection,
		position = 7
	)
	default boolean rareBuckler()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareDexScroll",
		name = "Celebrate Dex scroll",
		description = "On: a Dexterous prayer scroll gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Rigour. Technically purple.",
		section = rareSection,
		position = 8
	)
	default boolean rareDexScroll()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareArcaneScroll",
		name = "Celebrate Arcane scroll",
		description = "On: an Arcane prayer scroll gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Augury. Also technically purple.",
		section = rareSection,
		position = 9
	)
	default boolean rareArcaneScroll()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareOlmlet",
		name = "Celebrate Olmlet",
		description = "On: an Olmlet gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. The tiny Olm that follows you home. Or would have.",
		section = rareSection,
		position = 10
	)
	default boolean rareOlmlet()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareDust",
		name = "Celebrate Metamorphic dust",
		description = "On: Metamorphic dust gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Challenge Mode only.",
		section = rareSection,
		position = 11
	)
	default boolean rareDust()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rareKit",
		name = "Celebrate Twisted kit",
		description = "On: a Twisted ancestral colour kit gets the big glowing popup, sound and chat message. Off: it still drops and counts, but only shows in the small quiet chest. Challenge Mode only.",
		section = rareSection,
		position = 12
	)
	default boolean rareKit()
	{
		return true;
	}

	@Getter
	@RequiredArgsConstructor
	enum FomoSound
	{
		JACKPOT("Jackpot (bling + coins)", new int[]{SoundEffectID.BLING, SoundEffectID.BLING3, SoundEffectID.COINS_JINGLE_2}, new int[]{0, 450, 900}),
		BLING("Bling", new int[]{SoundEffectID.BLING}, new int[]{0}),
		BLING_2("Bling 2", new int[]{SoundEffectID.BLING2}, new int[]{0}),
		BLING_3("Bling 3", new int[]{SoundEffectID.BLING3}, new int[]{0}),
		BLING_4("Bling 4", new int[]{SoundEffectID.BLING4}, new int[]{0}),
		DOUBLE_BLING("Double bling", new int[]{SoundEffectID.BLING, SoundEffectID.BLING2}, new int[]{0, 350}),
		COINS("Coins", new int[]{SoundEffectID.COINS_JINGLE_2}, new int[]{0}),
		NONE("None", new int[0], new int[0]);

		private final String label;
		/** Sound effect ids, played in order. */
		private final int[] ids;
		/** When each one plays, in ms after the popup appears. */
		private final int[] delaysMs;

		@Override
		public String toString()
		{
			return label;
		}
	}
}

package com.chambersfomo;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.SoundEffectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.raids.Raid;
import net.runelite.client.plugins.raids.RaidRoom;
import net.runelite.client.plugins.raids.RoomType;
import net.runelite.client.plugins.raids.events.RaidScouted;
import net.runelite.client.plugins.raids.solver.Layout;
import net.runelite.client.plugins.raids.solver.Room;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Chambers FOMO",
	description = "Tracks every Chambers of Xeric layout you reroll and shows the purples you would have got",
	tags = {"cox", "chambers", "xeric", "raids", "reroll", "loot", "purple", "fomo"}
)
public class ChambersFomoPlugin extends Plugin
{
	private static final String DATA_KEY = "data";
	private static final String RAID_START_MESSAGE = "The raid has begun!";
	private static final String CHAT_PREFIX = "[Chambers FOMO] ";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChambersFomoConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PhantomPopupOverlay popupOverlay;

	@Inject
	private XpDropOverlay xpDropOverlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private MouseManager mouseManager;

	/** Closes the popup on any click, without eating the click. */
	private final MouseAdapter clickToClose = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (config.clickToClose())
			{
				popupOverlay.dismiss();
			}
			return event;
		}
	};

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	private final Random random = new Random();
	private final LootSimulator simulator = new LootSimulator(random);

	private FomoPanel panel;
	private NavigationButton navButton;
	private FomoData data = new FomoData();

	/** This session's Regret XP, for XP/hr. The session starts at the first XP gained. */
	private long sessionStart;
	private long sessionXp;
	private int sessionRerolls;
	/** When the last reroll gave XP, for the fast-reroll limit. */
	private long lastRerollAt;

	/** Bump when the Regret XP rates change, so old saves are recomputed. */
	private static final int XP_VERSION = 3;
	private boolean profileLoaded;

	/** The in-raid varbit as last seen. */
	private boolean inRaid;
	/** A layout is loaded that has not been started, so leaving it counts as a reroll. */
	private boolean pendingRoll;
	private String pendingLayout;

	@Provides
	ChambersFomoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChambersFomoConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(popupOverlay);
		xpDropOverlay.setIcon(icon());
		overlayManager.add(xpDropOverlay);
		mouseManager.registerMouseListener(clickToClose);
		panel = new FomoPanel(this, itemManager);
		navButton = NavigationButton.builder()
			.tooltip("Chambers FOMO")
			.icon(icon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(() ->
		{
			inRaid = client.getGameState() == GameState.LOGGED_IN
				&& client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
			loadData();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(popupOverlay);
		overlayManager.remove(xpDropOverlay);
		mouseManager.unregisterMouseListener(clickToClose);
		xpDropOverlay.clear();
		popupOverlay.clear();
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		pendingRoll = false;
		pendingLayout = null;
		inRaid = false;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		sessionStart = 0;
		sessionXp = 0;
		sessionRerolls = 0;
		loadData();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ChambersFomoConfig.GROUP.equals(event.getGroup()) && !DATA_KEY.equals(event.getKey()))
		{
			clientThread.invokeLater(this::refreshPanel);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.RAIDS_CLIENT_INDUNGEON)
		{
			return;
		}

		boolean nowIn = event.getValue() == 1;
		if (nowIn && !inRaid && !pendingRoll)
		{
			// A fresh raid instance: a new layout roll.
			pendingRoll = true;
			pendingLayout = null;
		}
		else if (!nowIn && inRaid)
		{
			resolvePending();
		}
		inRaid = nowIn;
	}

	@Subscribe
	public void onRaidScouted(RaidScouted event)
	{
		// The core Chambers of Xeric plugin found the layout. It can fire before or after the varbit.
		String layout = layoutOf(event.getRaid());
		if (layout == null)
		{
			return;
		}
		if (!pendingRoll && client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS) == 0)
		{
			pendingRoll = true;
			pendingLayout = null;
		}
		if (pendingRoll && (event.isFirstScout() || pendingLayout == null))
		{
			pendingLayout = layout;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION
			&& event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		if (pendingRoll && RAID_START_MESSAGE.equals(Text.removeTags(event.getMessage())))
		{
			// They committed to this layout, so it rolls real loot instead of phantom loot.
			pendingRoll = false;
			pendingLayout = null;
			data.raidsStarted++;
			save();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Logging out drops you from the raid, but the profile is already gone, so it is not counted.
			pendingRoll = false;
			pendingLayout = null;
			inRaid = false;
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		List<Integer> sounds = popupOverlay.dueSounds(System.currentTimeMillis());
		if (sounds.isEmpty())
		{
			return;
		}
		int volume = Math.round(config.soundVolume() * 127 / 100f);
		if (volume <= 0)
		{
			return;
		}
		for (int id : sounds)
		{
			client.playSoundEffect(id, volume);
		}
	}

	private void resolvePending()
	{
		if (!pendingRoll)
		{
			return;
		}
		pendingRoll = false;

		FomoData.Roll roll = new FomoData.Roll();
		roll.time = System.currentTimeMillis();
		roll.layout = pendingLayout;
		LootSimulator.RaidLoot raidLoot = simulator.roll(config.personalPoints(), config.teamPoints(), config.challengeMode());
		roll.loot = raidLoot.uniques;
		roll.common = raidLoot.common;
		pendingLayout = null;

		long gp = 0;
		for (Loot loot : roll.loot)
		{
			gp += priceOf(loot);
		}
		for (FomoData.Drop drop : roll.common)
		{
			gp += (long) itemManager.getItemPrice(drop.item.getItemId()) * drop.quantity;
		}
		long now = System.currentTimeMillis();
		double sinceLast = lastRerollAt == 0 ? -1 : (now - lastRerollAt) / 1000.0;
		lastRerollAt = now;
		roll.xp = RegretSkill.xpForRoll(RegretSkill.levelFor(data.xp), gp,
			!roll.loot.isEmpty(), roll.loot.contains(Loot.OLMLET), sinceLast);

		data.add(roll);
		gainXp(roll.xp);
		for (Loot loot : roll.loot)
		{
			long price = priceOf(loot);
			if (price > data.biggestMissGp)
			{
				data.biggestMissGp = price;
				data.biggestMissName = loot.getDisplayName();
			}
		}
		save();
		announce(roll.loot, roll.common, roll.layout);
	}

	private void announce(List<Loot> loot, List<FomoData.Drop> common, String layout)
	{
		if (loot.isEmpty())
		{
			showCommonChest(common);
			if (config.chatDryRolls() && !common.isEmpty())
			{
				StringBuilder items = new StringBuilder();
				long gp = 0;
				for (FomoData.Drop drop : common)
				{
					if (items.length() > 0)
					{
						items.append(", ");
					}
					items.append(QuantityFormatter.formatNumber(drop.quantity)).append(" x ").append(drop.item.getDisplayName());
					gp += (long) itemManager.getItemPrice(drop.item.getItemId()) * drop.quantity;
				}
				chat(new ChatMessageBuilder()
					.append(ChatColorType.HIGHLIGHT).append(CHAT_PREFIX)
					.append(ChatColorType.NORMAL)
					.append("No purple. That layout would have given you " + items
						+ " (" + QuantityFormatter.quantityToStackSize(gp) + " gp). Also not yours.")
					.build());
			}
			return;
		}

		// Items turned off under Rare items still dropped, but get no fanfare.
		List<Loot> hyped = new ArrayList<>();
		for (Loot l : loot)
		{
			if (rareEnabled(l))
			{
				hyped.add(l);
			}
		}

		long total = 0;
		List<int[]> items = new ArrayList<>();
		for (Loot l : loot)
		{
			total += priceOf(l);
			items.add(new int[]{l.getItemId(), 1});
		}
		String value = total > 0 ? "Value: " + QuantityFormatter.quantityToStackSize(total) + " gp" : "Value: priceless";

		if (hyped.isEmpty())
		{
			if (config.showCommonPopup())
			{
				popupOverlay.show(new PhantomPopupOverlay.Popup(items, null, Quips.muted(random), value, null,
					config.commonPopupSeconds() * 1000, ChambersFomoConfig.FomoSound.NONE));
			}
			return;
		}

		// One chest per roll, headlined by its rarest wanted item.
		Loot headline = hyped.get(0);
		for (Loot l : hyped)
		{
			if (rank(l) > rank(headline))
			{
				headline = l;
			}
		}
		String quip = Quips.forLoot(headline, random);
		if (config.chatMessages())
		{
			for (Loot l : hyped)
			{
				chat(new ChatMessageBuilder()
					.append(ChatColorType.HIGHLIGHT).append(CHAT_PREFIX)
					.append(ChatColorType.NORMAL).append("That layout would have given you ")
					.append(Color.MAGENTA, l.getDisplayName())
					.append(ChatColorType.NORMAL).append(" (" + priceText(l) + "). " + (l == headline ? quip : ""))
					.build());
			}
		}
		if (config.showPopup())
		{
			String footer = layout != null ? "Rerolled: " + layout : "Rerolled layout";
			popupOverlay.show(new PhantomPopupOverlay.Popup(
				items, headline, quip, value, footer, config.popupSeconds() * 1000, config.sound()));
		}
	}

	/** Whether a rare item gets the full popup, from the Rare items settings. */
	private boolean rareEnabled(Loot loot)
	{
		switch (loot)
		{
			case TWISTED_BOW:
				return config.rareTwistedBow();
			case KODAI_INSIGNIA:
				return config.rareKodai();
			case ELDER_MAUL:
				return config.rareElderMaul();
			case DRAGON_CLAWS:
				return config.rareDragonClaws();
			case ANCESTRAL_HAT:
			case ANCESTRAL_ROBE_TOP:
			case ANCESTRAL_ROBE_BOTTOM:
				return config.rareAncestral();
			case DINHS_BULWARK:
				return config.rareBulwark();
			case DRAGON_HUNTER_CROSSBOW:
				return config.rareDhcb();
			case TWISTED_BUCKLER:
				return config.rareBuckler();
			case DEXTEROUS_PRAYER_SCROLL:
				return config.rareDexScroll();
			case ARCANE_PRAYER_SCROLL:
				return config.rareArcaneScroll();
			case OLMLET:
				return config.rareOlmlet();
			case METAMORPHIC_DUST:
				return config.rareDust();
			case TWISTED_ANCESTRAL_KIT:
				return config.rareKit();
			default:
				return true;
		}
	}

	/** Shows the brief common-loot chest. */
	private void showCommonChest(List<FomoData.Drop> common)
	{
		if (common.isEmpty() || !config.showCommonPopup())
		{
			return;
		}
		long total = 0;
		List<int[]> items = new ArrayList<>();
		for (FomoData.Drop drop : common)
		{
			total += (long) itemManager.getItemPrice(drop.item.getItemId()) * drop.quantity;
			items.add(new int[]{drop.item.getItemId(), drop.quantity});
		}
		popupOverlay.show(new PhantomPopupOverlay.Popup(items, null, Quips.common(random),
			"Value: " + QuantityFormatter.quantityToStackSize(total) + " gp", null,
			config.commonPopupSeconds() * 1000, ChambersFomoConfig.FomoSound.NONE));
	}

	private static int rank(Loot loot)
	{
		switch (loot.getTier())
		{
			case MEGA:
				return 3;
			case PET:
				return 2;
			case PURPLE:
				return 1;
			default:
				return 0;
		}
	}

	/** Adds Regret XP, shows the drop and announces level-ups. Client thread. */
	private void gainXp(long xp)
	{
		int before = RegretSkill.levelFor(data.xp);
		data.xp = Math.min(RegretSkill.MAX_XP, data.xp + xp);
		int after = RegretSkill.levelFor(data.xp);

		long now = System.currentTimeMillis();
		if (sessionStart == 0)
		{
			sessionStart = now;
		}
		sessionXp += xp;
		sessionRerolls++;

		if (config.showXpDrops())
		{
			xpDropOverlay.drop(xp);
		}
		if (after > before)
		{
			announceLevel(after);
		}
	}

	private void announceLevel(int level)
	{
		String text = level >= RegretSkill.MAX_LEVEL
			? "Congratulations, you've reached the highest possible " + RegretSkill.NAME
				+ " level of 99. You may now buy a Skillcape of Regret. It is not for you."
			: "Congratulations, you've just advanced your " + RegretSkill.NAME + " level. You are now level " + level + ".";
		chat(new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append(text)
			.build());
		int volume = Math.round(config.soundVolume() * 127 / 100f);
		if (volume > 0)
		{
			client.playSoundEffect(SoundEffectID.BLING4, volume);
		}
	}

	// ---- Called by the panel's buttons (on the Swing thread) ----

	void resetSession()
	{
		clientThread.invokeLater(() ->
		{
			sessionStart = 0;
			sessionXp = 0;
			sessionRerolls = 0;
			lastRerollAt = 0;
			refreshPanel();
		});
	}

	void resetHistory()
	{
		clientThread.invokeLater(() ->
		{
			data = new FomoData();
			save();
		});
	}

	// ---- Saving and the panel ----

	private void loadData()
	{
		String json = configManager.getRSProfileConfiguration(ChambersFomoConfig.GROUP, DATA_KEY);
		profileLoaded = configManager.getRSProfileKey() != null;
		FomoData loaded = null;
		if (json != null)
		{
			try
			{
				loaded = gson.fromJson(json, FomoData.class);
			}
			catch (RuntimeException e)
			{
				log.warn("Could not read saved Chambers FOMO data", e);
			}
		}
		data = loaded == null ? new FomoData() : loaded.fixNulls();
		if (data.xpVersion < XP_VERSION)
		{
			recomputeXp();
		}
		refreshPanel();
	}

	/** Re-scores every saved reroll with the current XP rates and today's prices. */
	private void recomputeXp()
	{
		long total = 0;
		// Oldest first, so each reroll is scored at the level you were when you made it.
		for (int i = data.history.size() - 1; i >= 0; i--)
		{
			FomoData.Roll roll = data.history.get(i);
			long gp = 0;
			for (Loot loot : roll.loot)
			{
				gp += priceOf(loot);
			}
			for (FomoData.Drop drop : roll.common)
			{
				gp += (long) itemManager.getItemPrice(drop.item.getItemId()) * drop.quantity;
			}
			roll.xp = RegretSkill.xpForRoll(RegretSkill.levelFor(total), gp,
				!roll.loot.isEmpty(), roll.loot.contains(Loot.OLMLET), -1);
			total += roll.xp;
		}
		data.xp = Math.min(RegretSkill.MAX_XP, total);
		data.xpVersion = XP_VERSION;
		if (!data.history.isEmpty())
		{
			save();
		}
	}

	private void save()
	{
		if (configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(ChambersFomoConfig.GROUP, DATA_KEY, gson.toJson(data));
		}
		refreshPanel();
	}

	/** Builds a snapshot on the client thread (prices need it) and hands it to the panel. */
	private void refreshPanel()
	{
		FomoPanel p = panel;
		if (p == null)
		{
			return;
		}
		FomoData copy = gson.fromJson(gson.toJson(data), FomoData.class).fixNulls();
		Map<Loot, Long> prices = new EnumMap<>(Loot.class);
		for (Loot loot : Loot.values())
		{
			prices.put(loot, priceOf(loot));
		}
		Map<CommonLoot, Long> commonPrices = new EnumMap<>(CommonLoot.class);
		for (CommonLoot loot : CommonLoot.values())
		{
			commonPrices.put(loot, (long) itemManager.getItemPrice(loot.getItemId()));
		}
		double chance = LootSimulator.chanceOfYourPurple(config.personalPoints(), config.teamPoints());
		boolean loaded = profileLoaded;
		FomoPanel.Session session = new FomoPanel.Session(sessionStart, sessionXp, sessionRerolls);
		SwingUtilities.invokeLater(() -> p.update(copy, prices, commonPrices, chance, loaded, session));
	}

	private long priceOf(Loot loot)
	{
		return itemManager.getItemPrice(loot.getItemId());
	}

	private String priceText(Loot loot)
	{
		long price = priceOf(loot);
		if (price <= 0)
		{
			return "priceless, and not yours";
		}
		return QuantityFormatter.quantityToStackSize(price) + " gp";
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/** The combat and puzzle rooms of a scouted raid, in order. */
	private static String layoutOf(Raid raid)
	{
		if (raid == null || raid.getLayout() == null)
		{
			return null;
		}
		Layout layout = raid.getLayout();
		List<String> names = new ArrayList<>();
		for (Room room : layout.getRooms())
		{
			RaidRoom raidRoom = raid.getRoom(room.getPosition());
			if (raidRoom != null && Arrays.asList(RoomType.COMBAT, RoomType.PUZZLE).contains(raidRoom.getType()))
			{
				names.add(raidRoom.getName());
			}
		}
		return names.isEmpty() ? null : String.join(", ", names);
	}

	/** A little glowing purple orb for the sidebar. */
	static BufferedImage icon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setPaint(new GradientPaint(0, 0, new Color(225, 160, 255), 16, 16, new Color(110, 20, 170)));
		g.fill(new Ellipse2D.Float(1.5f, 1.5f, 13, 13));
		g.setStroke(new BasicStroke(1.2f));
		g.setColor(new Color(255, 205, 70));
		g.draw(new Ellipse2D.Float(1.5f, 1.5f, 13, 13));
		g.setColor(Color.WHITE);
		g.fill(new Ellipse2D.Float(4.5f, 4f, 3.5f, 3.5f));
		g.dispose();
		return img;
	}
}

