import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

/**
 * The Chambers of Xeric common (non-unique) rewards.
 *
 * A player without a unique gets two different items from the 33 table items,
 * each equally likely. The quantity scales with personal points up to
 * {@link #POINTS_CAP}, where it reaches {@link #getMax()}.
 */
@Getter
@RequiredArgsConstructor
public enum CommonLoot
{
	DEATH_RUNE("Death rune", ItemID.DEATHRUNE, 3640),
	BLOOD_RUNE("Blood rune", ItemID.BLOODRUNE, 4095),
	SOUL_RUNE("Soul rune", ItemID.SOULRUNE, 6553),
	RUNE_ARROW("Rune arrow", ItemID.RUNE_ARROW, 9362),
	DRAGON_ARROW("Dragon arrow", ItemID.DRAGON_ARROW, 648),
	GRIMY_RANARR("Grimy ranarr weed", ItemID.UNIDENTIFIED_RANARR, 138),
	GRIMY_TOADFLAX("Grimy toadflax", ItemID.UNIDENTIFIED_TOADFLAX, 210),
	GRIMY_IRIT("Grimy irit leaf", ItemID.UNIDENTIFIED_IRIT, 675),
	GRIMY_AVANTOE("Grimy avantoe", ItemID.UNIDENTIFIED_AVANTOE, 337),
	GRIMY_KWUARM("Grimy kwuarm", ItemID.UNIDENTIFIED_KWUARM, 289),
	GRIMY_SNAPDRAGON("Grimy snapdragon", ItemID.UNIDENTIFIED_SNAPDRAGON, 84),
	GRIMY_CADANTINE("Grimy cadantine", ItemID.UNIDENTIFIED_CADANTINE, 330),
	GRIMY_LANTADYME("Grimy lantadyme", ItemID.UNIDENTIFIED_LANTADYME, 442),
	GRIMY_DWARF_WEED("Grimy dwarf weed", ItemID.UNIDENTIFIED_DWARF_WEED, 546),
	GRIMY_TORSTOL("Grimy torstol", ItemID.UNIDENTIFIED_TORSTOL, 134),
	SILVER_ORE("Silver ore", ItemID.SILVER_ORE, 6553),
	COAL("Coal", ItemID.COAL, 6553),
	GOLD_ORE("Gold ore", ItemID.GOLD_ORE, 2978),
	MITHRIL_ORE("Mithril ore", ItemID.MITHRIL_ORE, 4095),
	ADAMANTITE_ORE("Adamantite ore", ItemID.ADAMANTITE_ORE, 789),
	RUNITE_ORE("Runite ore", ItemID.RUNITE_ORE, 65),
	UNCUT_SAPPHIRE("Uncut sapphire", ItemID.UNCUT_SAPPHIRE, 697),
	UNCUT_EMERALD("Uncut emerald", ItemID.UNCUT_EMERALD, 923),
	UNCUT_RUBY("Uncut ruby", ItemID.UNCUT_RUBY, 541),
	UNCUT_DIAMOND("Uncut diamond", ItemID.UNCUT_DIAMOND, 258),
	LIZARDMAN_FANG("Lizardman fang", ItemID.LIZARDMAN_FANG, 4681),
	PURE_ESSENCE("Pure essence", ItemID.BLANKRUNE_HIGH, 65535),
	SALTPETRE("Saltpetre", ItemID.HOSIDIUS_SALTPETRE, 4681),
	TEAK_PLANK("Teak plank", ItemID.PLANK_TEAK, 1365),
	MAHOGANY_PLANK("Mahogany plank", ItemID.PLANK_MAHOGANY, 550),
	DYNAMITE("Dynamite", ItemID.LOVAKENGJ_DYNAMITE_FUSED, 2427),
	TORN_PRAYER_SCROLL("Torn prayer scroll", ItemID.RAIDS_PRAYERSCROLL_PRESERVE, 1),
	DARK_RELIC("Dark relic", ItemID.RAIDS_ANCIENT_RELIC, 1),

	/** Not on the table: 1/12 for players without a unique. */
	ELITE_CLUE("Clue scroll (elite)", ItemID.TRAIL_ELITE_EMOTE_EXP1, 0);

	/** Common loot stops growing past this many personal points. */
	public static final int POINTS_CAP = 131_071;
	/** How many items are on the table (all but the clue). */
	public static final int TABLE_SIZE = 33;

	private final String displayName;
	private final int itemId;
	/** The quantity at {@link #POINTS_CAP} points; 0 for items that are not on the table. */
	private final int max;

	boolean onTable()
	{
		return max > 0;
	}

	/** How many you get for the given personal points: points / (131,071 / max), at least 1. */
	int quantity(int points)
	{
		if (max <= 1)
		{
			return 1;
		}
		int divisor = POINTS_CAP / max;
		return Math.max(1, Math.min(points, POINTS_CAP) / divisor);
	}
}

package com.chambersfomo;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/** Everything the plugin saves per RuneScape profile, stored as JSON. */
class FomoData
{
	/** How many history rows are kept. The counters below keep counting past this. */
	static final int MAX_HISTORY = 300;

	/** Rerolled layouts that got a phantom loot roll. */
	int rerolls;

	/** Raids the player actually started (no phantom roll for those). */
	int raidsStarted;
	/** Rerolls since the last phantom purple. */
	int rollsSinceLastPurple;
	/** The worst miss so far, in gp at the time it happened. */
	long biggestMissGp;
	String biggestMissName;
	/** Total XP in the fake Regret skill. */
	long xp;
	/** Which XP rates {@link #xp} was earned with; older saves get recomputed. */
	int xpVersion;
	/** Phantom purple counts. */
	Map<Loot, Integer> counts = new EnumMap<>(Loot.class);
	/** Phantom common loot totals. */
	Map<CommonLoot, Long> commonCounts = new EnumMap<>(CommonLoot.class);
	/** Newest first. */
	List<Roll> history = new ArrayList<>();

	static class Roll
	{
		long time;
		/** Room names in order, or null if the layout was not scouted. */
		String layout;
		/** Purples (and pet, dust, kit). */
		List<Loot> loot = new ArrayList<>();
		/** Common loot, only when there was no purple. */
		List<Drop> common = new ArrayList<>();
		/** Regret XP this reroll gave. */
		long xp;
	}

	static class Drop
	{
		CommonLoot item;
		int quantity;

		Drop(CommonLoot item, int quantity)
		{
			this.item = item;
			this.quantity = quantity;
		}
	}

	void add(Roll roll)
	{
		rerolls++;
		if (roll.loot.isEmpty())
		{
			rollsSinceLastPurple++;
		}
		else
		{
			rollsSinceLastPurple = 0;
		}
		for (Loot loot : roll.loot)
		{
			counts.merge(loot, 1, Integer::sum);
		}
		for (Drop drop : roll.common)
		{
			commonCounts.merge(drop.item, (long) drop.quantity, Long::sum);
		}
		history.add(0, roll);
		while (history.size() > MAX_HISTORY)
		{
			history.remove(history.size() - 1);
		}
	}

	/** Gson leaves fields null when they are missing from old saves. */
	FomoData fixNulls()
	{
		if (counts == null)
		{
			counts = new EnumMap<>(Loot.class);
		}
		else
		{
			counts.remove(null);
		}
		if (commonCounts == null)
		{
			commonCounts = new EnumMap<>(CommonLoot.class);
		}
		else
		{
			commonCounts.remove(null);
		}
		if (history == null)
		{
			history = new ArrayList<>();
		}
		for (Roll roll : history)
		{
			if (roll.loot == null)
			{
				roll.loot = new ArrayList<>();
			}
			roll.loot.removeIf(l -> l == null);
			if (roll.common == null)
			{
				roll.common = new ArrayList<>();
			}
			roll.common.removeIf(d -> d == null || d.item == null);
		}
		return this;
	}
}

