				plugin.resetHistory();
			}
		});
		add(left(reset));

		// XP/hr keeps moving between rerolls.
		clock = new Timer(1000, e -> updateRates());
	}

	/** This session's numbers for XP/hr. */
	static final class Session
	{
		final long start;
		final long xp;
		final int rerolls;

		Session(long start, long xp, int rerolls)
		{
			this.start = start;
			this.xp = xp;
			this.rerolls = rerolls;
		}
	}

	@Override
	public void onActivate()
	{
		clock.start();
	}

	@Override
	public void onDeactivate()
	{
		clock.stop();
	}

	private void updateRates()
	{
		sessionXpLabel.setText(QuantityFormatter.formatNumber(session.xp));
		if (session.start == 0)
		{
			xpPerHour.setText("0");
			rerollsPerHour.setText("0");
			return;
		}
		// At least a minute, so the first reroll doesn't show millions per hour.
		double hours = Math.max(60_000, System.currentTimeMillis() - session.start) / 3_600_000.0;
		xpPerHour.setText(QuantityFormatter.formatNumber((long) (session.xp / hours)));
		rerollsPerHour.setText(String.valueOf((long) (session.rerolls / hours)));
	}

	/** Called on the Swing thread with a copy of the saved data. */
	void update(FomoData data, Map<Loot, Long> prices, Map<CommonLoot, Long> commonPrices,
		double chancePerRaid, boolean loggedIn, Session session)
	{
		this.session = session;
		int level = RegretSkill.levelFor(data.xp);
		skillLevel.setText(" " + RegretSkill.NAME + "  -  Level " + level);
		totalXp.setText(QuantityFormatter.formatNumber(data.xp));
		if (level >= RegretSkill.MAX_LEVEL)
		{
			skillBar.setMaximumValue(1);
			skillBar.setValue(1);
			skillBar.setLeftLabel("Lvl 99");
			skillBar.setRightLabel("200M");
			skillBar.setCenterLabel("Maxed. Sadly.");
			xpToLevel.setText("-");
		}
		else
		{
			long from = RegretSkill.xpForLevel(level);
			long to = RegretSkill.xpForLevel(level + 1);
			skillBar.setMaximumValue((int) (to - from));
			skillBar.setValue((int) (data.xp - from));
			skillBar.setLeftLabel("Lvl " + level);
			skillBar.setRightLabel("Lvl " + (level + 1));
			skillBar.setCenterLabel((int) (100.0 * (data.xp - from) / (to - from)) + "%");
			xpToLevel.setText(QuantityFormatter.formatNumber(to - data.xp));
		}
		updateRates();

		notice.setText(loggedIn ? "" : "<html>Log in to load this account's regrets.</html>");

		int purpleCount = 0;
		long gp = 0;
		for (Map.Entry<Loot, Integer> e : data.counts.entrySet())
		{
			if (e.getKey().getTier() != Loot.Tier.PET)
			{
				purpleCount += e.getValue();
			}
			gp += prices.getOrDefault(e.getKey(), 0L) * e.getValue();
		}

		long commonGp = 0;
		for (Map.Entry<CommonLoot, Long> e : data.commonCounts.entrySet())
		{
			commonGp += commonPrices.getOrDefault(e.getKey(), 0L) * e.getValue();
		}

		rerolls.setText(String.valueOf(data.rerolls));
		started.setText(String.valueOf(data.raidsStarted));
		purples.setText(String.valueOf(purpleCount));
		gpMissed.setText(QuantityFormatter.quantityToStackSize(gp + commonGp));
		gpPurples.setText(QuantityFormatter.quantityToStackSize(gp));
		gpCommon.setText(QuantityFormatter.quantityToStackSize(commonGp));
		dryStreak.setText(String.valueOf(data.rollsSinceLastPurple));
		expected.setText(chancePerRaid <= 0 ? "-" : String.format("1 in %.0f", 1 / chancePerRaid));
		worst.setText(data.biggestMissName == null ? "-" : data.biggestMissName);
		worst.setToolTipText(data.biggestMissName == null ? null
			: QuantityFormatter.quantityToStackSize(data.biggestMissGp) + " gp at the time");

		logGrid.removeAll();
		for (Loot loot : Loot.values())
		{
			int count = data.counts.getOrDefault(loot, 0);
			JLabel cell = new JLabel();
			cell.setHorizontalAlignment(SwingConstants.CENTER);
			cell.setPreferredSize(new Dimension(36, 32));
			cell.setToolTipText(loot.getDisplayName() + ": " + count);
			AsyncBufferedImage img = count > 0
				? itemManager.getImage(loot.getItemId(), count, true)
				: itemManager.getImage(loot.getItemId());
			img.addTo(cell);
			cell.setEnabled(count > 0);
			logGrid.add(cell);
		}

		commonGrid.removeAll();
		List<CommonLoot> got = new ArrayList<>();
		for (CommonLoot loot : CommonLoot.values())
		{
			if (data.commonCounts.getOrDefault(loot, 0L) > 0)
			{
				got.add(loot);
			}
		}
		// Most valuable pile first.
		got.sort(Comparator.comparingLong((CommonLoot l) ->
			commonPrices.getOrDefault(l, 0L) * data.commonCounts.get(l)).reversed());
		for (CommonLoot loot : got)
		{
			long count = data.commonCounts.get(loot);
			long value = commonPrices.getOrDefault(loot, 0L) * count;
			JLabel cell = new JLabel();
			cell.setHorizontalAlignment(SwingConstants.CENTER);
			cell.setPreferredSize(new Dimension(36, 32));
			cell.setToolTipText(QuantityFormatter.formatNumber(count) + " x " + loot.getDisplayName()
				+ (value > 0 ? " (" + QuantityFormatter.quantityToStackSize(value) + " gp)" : ""));
			itemManager.getImage(loot.getItemId(), (int) Math.min(Integer.MAX_VALUE, count), true).addTo(cell);
			commonGrid.add(cell);
		}
		commonGrid.setLayout(got.isEmpty() ? new GridLayout(1, 1) : new GridLayout(0, 5, 2, 2));
		if (got.isEmpty())
		{
			JLabel none = new JLabel("Nothing yet.");
			none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			commonGrid.add(none);
		}

		history.removeAll();
		if (data.history.isEmpty())
		{
			JLabel none = new JLabel("<html>No rerolls yet. Go scout a layout you hate.</html>");
			none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			history.add(left(none));
		}
		SimpleDateFormat time = new SimpleDateFormat("MMM d, h:mm a");
		int n = data.rerolls;
		for (int i = 0; i < Math.min(HISTORY_SHOWN, data.history.size()); i++)
		{
			history.add(left(row(data.history.get(i), n - i, time)));
			history.add(Box.createVerticalStrut(3));
		}

		revalidate();
		repaint();
	}

	private JPanel row(FomoData.Roll roll, int number, SimpleDateFormat time)
	{
		JPanel row = new JPanel(new BorderLayout());
		boolean hit = !roll.loot.isEmpty();
		row.setBackground(hit ? new Color(55, 25, 75) : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, hit ? PURPLE : ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 4)));

		StringBuilder loot = new StringBuilder();
		for (Loot l : roll.loot)
		{
			if (loot.length() > 0)
			{
				loot.append(", ");
			}
			loot.append(l.getDisplayName());
		}
		StringBuilder common = new StringBuilder();
		for (FomoData.Drop d : roll.common)
		{
			if (common.length() > 0)
			{
				common.append(", ");
			}
			common.append(QuantityFormatter.formatNumber(d.quantity)).append(" x ").append(d.item.getDisplayName());
		}
		String layout = roll.layout == null ? "Layout not scouted" : roll.layout;
		String result = hit
			? "<font color='#c878ff'><b>" + escape(loot.toString()) + "</b></font>"
			: "<font color='#8a8a8a'>" + (common.length() == 0 ? "nothing" : escape(common.toString())) + "</font>";
		JLabel text = new JLabel("<html><font color='#a0a0a0'>#" + number + " &middot; "
			+ time.format(new Date(roll.time))
			+ (roll.xp > 0 ? " &middot; <font color='#c878ff'>+" + QuantityFormatter.formatNumber(roll.xp) + " xp</font>" : "")
			+ "</font><br>"
			+ escape(layout) + "<br>&rarr; " + result + "</html>");
		text.setFont(FontManager.getRunescapeSmallFont());
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static JLabel value()
	{
		JLabel l = new JLabel("0");
		l.setForeground(Color.WHITE);
		l.setHorizontalAlignment(SwingConstants.RIGHT);
		return l;
	}

	private static void stat(JPanel stats, String name, JLabel value)
	{
		JLabel label = new JLabel(name);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stats.add(label);
		stats.add(value);
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(GOLD);
		return l;
	}

	private static JButton button(String text, Runnable action)
	{
		JButton b = new JButton(text);
		b.setFocusable(false);
		b.addActionListener(e -> action.run());
		return b;
	}

	private static <T extends Component> T left(T c)
	{
		if (c instanceof javax.swing.JComponent)
		{
			((javax.swing.JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		return c;
	}
}

