package com.chambersfomo;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Rolls the rewards of one deathless Chambers of Xeric completion, using the
 * published rates (OSRS wiki, Ancient chest, after the 12 August 2026 reweight):
 * <ul>
 * <li>Every 8,676 team points gives 1% chance of a unique, capped at
 * 570,000 points (65.7%) per roll. Points past the cap roll again, up to six uniques.</li>
 * <li>Each unique goes to a player weighted by their share of the points.</li>
 * <li>The item comes from the weighted table (out of 60, or 56 in Challenge Mode).</li>
 * <li>Each unique you receive carries a 1/53 Olmlet roll.</li>
 * <li>Without a unique you get two different common items and a 1/12 elite clue.</li>
 * <li>A timed Challenge Mode completion has a 1/75 kit and a 1/400 dust chance.</li>
 * </ul>
 */
public final class LootSimulator
{
	public static final double POINTS_PER_PERCENT = 8676.0;
	public static final int POINTS_CAP_PER_ROLL = 570_000;
	public static final int MAX_UNIQUES = 6;
	public static final int OLMLET_RATE = 53;
	public static final int ELITE_CLUE_RATE = 12;
	public static final int KIT_RATE = 75;
	public static final int DUST_RATE = 400;

	private final Random random;

	public LootSimulator(Random random)
	{
		this.random = random;
	}

	/** One raid's worth of loot for you. */
	public static final class RaidLoot
	{
		public final List<Loot> uniques = new ArrayList<>();
		public final List<FomoData.Drop> common = new ArrayList<>();
	}

	/** The chance one unique roll hits for the given points (already capped). */
	public static double uniqueChance(int points)
	{
		return Math.min(points, POINTS_CAP_PER_ROLL) / (POINTS_PER_PERCENT * 100.0);
	}

	/** The chance that a raid gives you at least one unique, for display. */
	public static double chanceOfYourPurple(int personalPoints, int teamPoints)
	{
		int team = Math.max(teamPoints, personalPoints);
		if (team <= 0)
		{
			return 0;
		}
		double share = personalPoints / (double) team;
		double none = 1.0;
		int left = team;
		for (int i = 0; i < MAX_UNIQUES && left > 0; i++)
		{
			none *= 1.0 - uniqueChance(left) * share;
			left -= POINTS_CAP_PER_ROLL;
		}
		return 1.0 - none;
	}

	/**
	 * Rolls one raid.
	 *
	 * @param personalPoints your points
	 * @param teamPoints the whole team's points; a value below personalPoints means solo
	 */
	public RaidLoot roll(int personalPoints, int teamPoints, boolean challengeMode)
	{
		RaidLoot loot = new RaidLoot();
		int team = Math.max(teamPoints, personalPoints);
		if (team <= 0)
		{
			return loot;
		}

		double share = personalPoints / (double) team;
		int left = team;
		for (int i = 0; i < MAX_UNIQUES && left > 0; i++)
		{
			if (random.nextDouble() < uniqueChance(left) && random.nextDouble() < share)
			{
				loot.uniques.add(rollTable(challengeMode));
				if (random.nextInt(OLMLET_RATE) == 0)
				{
					loot.uniques.add(Loot.OLMLET);
				}
			}
			left -= POINTS_CAP_PER_ROLL;
		}

		if (loot.uniques.isEmpty())
		{
			// Two different common items, and maybe a clue.
			CommonLoot[] all = CommonLoot.values();
			int first = random.nextInt(CommonLoot.TABLE_SIZE);
			int second = random.nextInt(CommonLoot.TABLE_SIZE - 1);
			if (second >= first)
			{
				second++;
			}
			loot.common.add(new FomoData.Drop(all[first], all[first].quantity(personalPoints)));
			loot.common.add(new FomoData.Drop(all[second], all[second].quantity(personalPoints)));
			if (random.nextInt(ELITE_CLUE_RATE) == 0)
			{
				loot.common.add(new FomoData.Drop(CommonLoot.ELITE_CLUE, 1));
			}
		}

		if (challengeMode)
		{
			if (random.nextInt(KIT_RATE) == 0)
			{
				loot.uniques.add(Loot.TWISTED_ANCESTRAL_KIT);
			}
			if (random.nextInt(DUST_RATE) == 0)
			{
				loot.uniques.add(Loot.METAMORPHIC_DUST);
			}
		}
		return loot;
	}

	/** Picks one item from the weighted unique table. */
	public Loot rollTable(boolean challengeMode)
	{
		int total = challengeMode ? Loot.TABLE_TOTAL_CM : Loot.TABLE_TOTAL;
		int pick = random.nextInt(total);
		for (Loot loot : Loot.values())
		{
			pick -= challengeMode ? loot.getWeightCm() : loot.getWeight();
			if (pick < 0)
			{
				return loot;
			}
		}
		throw new IllegalStateException("unique table weights do not add up to " + total);
	}
}

package com.chambersfomo;

import java.awt.AlphaComposite;
