/**
 * The phantom loot popup, drawn as the Chambers of Xeric reward chest window
 * (interface 539) from the game's own sprites. Rare loot gets glow, rays, sparkles
 * and a flashing border around the window; common loot shows briefly and quietly.
 */
@Singleton
class PhantomPopupOverlay extends Overlay
{
	// Window size and layout from the cache: 260x220, content inset 10px, buttons 36x36.
	private static final int W = 260;
	private static final int H = 220;
	private static final int TITLE_H = 28;
	private static final String TITLE = "Chambers of Xeric";
	/** Every chest says so, so it can't pass for a real reward screenshot. */
	private static final String PHANTOM_NOTE = "Phantom loot - not yours";

	// Sprites from the cache (SpriteID gamevals).
	private static final int SPRITE_BACKING = 297;
	private static final int SPRITE_CORNER_TL = 310;
	private static final int SPRITE_CORNER_TR = 311;
	private static final int SPRITE_CORNER_BL = 312;
	private static final int SPRITE_CORNER_BR = 313;
	private static final int SPRITE_EDGE_TOP = 314;
	private static final int SPRITE_EDGE_SIDE = 315;
	private static final int SPRITE_DIVIDER = 2546;
	private static final int SPRITE_CLOSE = 1731;
	private static final int SPRITE_BUTTON = 170;
	private static final int SPRITE_ICON_INVENTORY = 1226;
	private static final int SPRITE_ICON_BANK = 1227;
	private static final int SPRITE_ICON_DISCARD = 1235;

	private static final Color TITLE_ORANGE = new Color(0xff981f);
	private static final Color GOLD = new Color(255, 205, 70);
	private static final Color PURPLE = new Color(185, 80, 255);
	private static final int QUIP_START_MS = 700;
	private static final int QUIP_MS_PER_CHAR = 24;

	private final Client client;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final Deque<Popup> queue = new ArrayDeque<>();
	private Popup current;

	@Inject
	PhantomPopupOverlay(Client client, ItemManager itemManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	static final class Popup
	{
		/** Item id and quantity pairs, shown in the chest. */
		final List<int[]> items;
		/** The best rare item, or null for a common-loot chest. */
		final Loot headline;
		final String quip;
		final String value;
		final String footer;
		final int durationMs;
		final int[] soundIds;
		final int[] soundDelays;
		final List<float[]> sparkles = new ArrayList<>();
		long shownAt;
		int nextSound;

		Popup(List<int[]> items, Loot headline, String quip, String value, String footer,
			int durationMs, ChambersFomoConfig.FomoSound sound)
		{
			this.items = items;
			this.headline = headline;
			this.quip = quip;
			this.value = value;
			this.footer = footer;
			this.durationMs = durationMs;
			this.soundIds = sound.getIds();
			this.soundDelays = sound.getDelaysMs();
			if (headline != null)
			{
				Random r = new Random();
				int count = headline.getTier() == Loot.Tier.MEGA ? 46 : 30;
				for (int i = 0; i < count; i++)
				{
					// Around the window's edge: x, y, phase, speed, size.
					float side = r.nextFloat() * 4;
					float along = r.nextFloat();
					float off = 6 + r.nextFloat() * 34;
					float x;
					float y;
					if (side < 1)
					{
						x = (along - 0.5f) * (W + 40);
						y = -H / 2f - off;
					}
					else if (side < 2)
					{
						x = (along - 0.5f) * (W + 40);
						y = H / 2f + off;
					}
					else if (side < 3)
					{
						x = -W / 2f - off;
						y = (along - 0.5f) * (H + 40);
					}
					else
					{
						x = W / 2f + off;
						y = (along - 0.5f) * (H + 40);
					}
					sparkles.add(new float[]{x, y, r.nextFloat() * 6.28f, 0.002f + r.nextFloat() * 0.005f, 4 + r.nextFloat() * 7});
				}
			}
		}

		boolean rare()
		{
			return headline != null;
		}
	}

	/**
	 * Queues a popup. A common chest never waits: it replaces any common chest on
	 * screen or queued, and a rare chest cuts a common one short.
	 */
	synchronized void show(Popup popup)
	{
		queue.removeIf(p -> !p.rare());
		if (current != null && !current.rare())
		{
			current = null;
		}
		if (popup.rare() || current == null)
		{
			queue.add(popup);
		}
	}

	/**
	 * Closes the popup on screen, if any. Anything queued behind it shows next.
	 *
	 * @return whether a popup was closed
	 */
	synchronized boolean dismiss()
	{
		if (current == null)
		{
			return false;
		}
		current = null;
		return true;
	}

	synchronized void clear()
	{
		queue.clear();
		current = null;
	}

	private synchronized Popup active(long now)
	{
		if (current != null && now - current.shownAt > current.durationMs)
		{
			current = null;
		}
		if (current == null)
		{
			current = queue.poll();
			if (current != null)
			{
				current.shownAt = now;
			}
		}
		return current;
	}

	/** Sound effect ids whose time has come. Called every client tick. */
	synchronized List<Integer> dueSounds(long now)
	{
		List<Integer> due = new ArrayList<>();
		Popup p = active(now);
		if (p == null)
		{
			return due;
		}
		while (p.nextSound < p.soundIds.length && now - p.shownAt >= p.soundDelays[p.nextSound])
		{
			due.add(p.soundIds[p.nextSound++]);
		}
		return due;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		Popup p = active(now);
		if (p == null)
		{
			return null;
		}

		float t = now - p.shownAt;
		boolean rare = p.rare();
		float in = clamp(t / (rare ? 380f : 120f));
		float out = clamp((p.durationMs - t) / (rare ? 600f : 250f));
		float alpha = Math.min(in, out);
		float scale = rare ? easeOutBack(in) * (0.92f + 0.08f * out) : 1f;
		float pulse = (float) (0.5 + 0.5 * Math.sin(t / 200.0));

		int vx = client.getViewportXOffset();
		int vy = client.getViewportYOffset();
		int vw = client.getViewportWidth();
		int vh = client.getViewportHeight();
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

			if (rare)
			{
				g.setComposite(AlphaComposite.SrcOver.derive(0.35f * alpha));
				g.setColor(Color.BLACK);
				g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
			}
			g.setComposite(AlphaComposite.SrcOver.derive(Math.max(0f, alpha)));
			g.translate(vx + vw / 2f, vy + vh * (rare ? 0.46f : 0.5f));
			g.scale(scale, scale);

			if (rare)
			{
				boolean mega = p.headline.getTier() == Loot.Tier.MEGA;
				drawGlow(g, pulse, mega);
				drawRays(g, t, mega);
				drawEdgeFlash(g, t, pulse, mega);
				drawSparkles(g, p, t);
			}

			// The window itself is drawn at integer pixels, like the game.
			g.translate(-W / 2, -H / 2);
			drawWindow(g);
			drawContents(g, p, t, pulse);

			if (rare)
			{
				g.translate(W / 2, H / 2);
				drawHeader(g, p, t);
				drawQuip(g, p, t);
			}
		}
		finally
		{
			g.dispose();
		}
		return null;
	}

	// ---- The window, from the game's sprites ----

	private void drawWindow(Graphics2D g)
	{
		BufferedImage back = sprite(SPRITE_BACKING);
		BufferedImage top = sprite(SPRITE_EDGE_TOP);
		BufferedImage side = sprite(SPRITE_EDGE_SIDE);
		BufferedImage tl = sprite(SPRITE_CORNER_TL);
		BufferedImage tr = sprite(SPRITE_CORNER_TR);
		BufferedImage bl = sprite(SPRITE_CORNER_BL);
		BufferedImage br = sprite(SPRITE_CORNER_BR);
		if (back == null || top == null || side == null || tl == null || tr == null || bl == null || br == null)
		{
			// Sprites still loading: a plain stand-in for a frame or two.
			g.setColor(new Color(62, 53, 41));
			g.fillRect(0, 0, W, H);
			g.setColor(Color.BLACK);
			g.drawRect(0, 0, W - 1, H - 1);
		}
		else
		{
			Shape clip = g.getClip();
			g.clipRect(0, 0, W, H);
			for (int x = 0; x < W; x += back.getWidth())
			{
				for (int y = 0; y < H; y += back.getHeight())
				{
					g.drawImage(back, x, y, null);
				}
			}
			g.setClip(clip);
			g.clipRect(tl.getWidth(), 0, W - tl.getWidth() - tr.getWidth(), H);
			for (int x = tl.getWidth(); x < W - tr.getWidth(); x += top.getWidth())
			{
				g.drawImage(top, x, 0, null);
				g.drawImage(top, x, H - top.getHeight(), x + top.getWidth(), H, 0, top.getHeight(), top.getWidth(), 0, null);
			}
			g.setClip(clip);
			g.clipRect(0, tl.getHeight(), W, H - tl.getHeight() - bl.getHeight());
			for (int y = tl.getHeight(); y < H - bl.getHeight(); y += side.getHeight())
			{
				g.drawImage(side, W - side.getWidth(), y, null);
				g.drawImage(side, 0, y, side.getWidth(), y + side.getHeight(), side.getWidth(), 0, 0, side.getHeight(), null);
			}
			g.setClip(clip);
			g.drawImage(tl, 0, 0, null);
			g.drawImage(tr, W - tr.getWidth(), 0, null);
			g.drawImage(bl, 0, H - bl.getHeight(), null);
			g.drawImage(br, W - br.getWidth(), H - br.getHeight(), null);
		}

		BufferedImage divider = sprite(SPRITE_DIVIDER);
		if (divider != null)
		{
			Shape clip = g.getClip();
			g.clipRect(6, 0, W - 12, H);
			for (int x = 6; x < W - 6; x += divider.getWidth())
			{
				g.drawImage(divider, x, TITLE_H, null);
			}
			g.setClip(clip);
		}
		BufferedImage close = sprite(SPRITE_CLOSE);
		if (close != null)
		{
			g.drawImage(close, W - close.getWidth() - 7, 6, null);
		}

		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int tx = (W - fm.stringWidth(TITLE)) / 2;
		g.setColor(Color.BLACK);
		g.drawString(TITLE, tx + 1, 21);
		g.setColor(TITLE_ORANGE);
		g.drawString(TITLE, tx, 20);

		// The content area, then the Discard, Bank-all and Take-all buttons along the bottom.
		g.setColor(new Color(0, 0, 0, 80));
		g.fillRect(10, TITLE_H + 12, W - 20, H - TITLE_H - 22);
		int by = H - 10 - 36;
		button(g, 10, by, SPRITE_ICON_DISCARD, 3);
		button(g, W - 10 - 76, by, SPRITE_ICON_BANK, 3);
		button(g, W - 10 - 36, by, SPRITE_ICON_INVENTORY, 5);
	}

	private void button(Graphics2D g, int x, int y, int icon, int iconX)
	{
		BufferedImage back = sprite(SPRITE_BUTTON);
		BufferedImage img = sprite(icon);
		if (back != null)
		{
			g.drawImage(back, x, y, null);
		}
		if (img != null)
		{
			g.drawImage(img, x + iconX, y + 7, null);
		}
	}

	private void drawContents(Graphics2D g, Popup p, float t, float pulse)
	{
		int top = TITLE_H + 16;
		if (p.rare())
		{
			// The headline item, big, on a glowing slot.
			int cy = top + 44;
			float halo = 34 + 6 * pulse;
			g.setPaint(new RadialGradientPaint(W / 2f, cy, halo, new float[]{0f, 1f},
				new Color[]{new Color(210, 120, 255, 210), new Color(150, 60, 220, 0)}));
			g.fill(new Ellipse2D.Float(W / 2f - halo, cy - halo, halo * 2, halo * 2));
			BufferedImage img = itemManager.getImage(p.headline.getItemId());
			if (img != null)
			{
				int bob = (int) Math.round(Math.sin(t / 380.0) * 2);
				g.drawImage(img, W / 2 - img.getWidth(), cy - img.getHeight() + bob, img.getWidth() * 2, img.getHeight() * 2, null);
			}
			// Any other items (a pet with the purple, say) at normal size.
			int x = W / 2 + 44;
			for (int[] item : p.items)
			{
				if (item[0] == p.headline.getItemId())
				{
					continue;
				}
				BufferedImage other = itemManager.getImage(item[0], item[1], item[1] > 1);
				if (other != null)
				{
					g.drawImage(other, x, cy - 16, null);
					x += 38;
				}
			}

			g.setFont(FontManager.getRunescapeBoldFont());
			centered(g, p.headline.getDisplayName(), W / 2f, top + 98, new Color(230, 180, 255));
			g.setFont(FontManager.getRunescapeFont());
			centered(g, p.value, W / 2f, top + 114, Color.YELLOW);
			g.setFont(FontManager.getRunescapeSmallFont());
			centered(g, PHANTOM_NOTE, W / 2f, top + 127, new Color(200, 150, 230));
			return;
		}

		// Common chest: an inventory-style grid of slots, like the real one.
		int cols = Math.min(4, Math.max(1, p.items.size()));
		int gridW = cols * 42 - 6;
		int x0 = (W - gridW) / 2;
		int y0 = top + 10;
		for (int i = 0; i < p.items.size(); i++)
		{
			int[] item = p.items.get(i);
			BufferedImage img = itemManager.getImage(item[0], item[1], true);
			if (img != null)
			{
				g.drawImage(img, x0 + (i % 4) * 42, y0 + (i / 4) * 36, null);
			}
		}
		g.setFont(FontManager.getRunescapeFont());
		centered(g, p.value, W / 2f, top + 70, Color.YELLOW);
		g.setFont(FontManager.getRunescapeSmallFont());
		centered(g, p.quip, W / 2f, top + 88, new Color(200, 190, 170));
		centered(g, PHANTOM_NOTE, W / 2f, top + 104, new Color(200, 150, 230));
	}

	// ---- Rare-loot flash around the window ----

	private void drawGlow(Graphics2D g, float pulse, boolean mega)
	{
		float r = (mega ? 320 : 270) + 35 * pulse;
		g.setPaint(new RadialGradientPaint(0, 0, r, new float[]{0f, 0.5f, 1f},
			new Color[]{withAlpha(PURPLE, 170), withAlpha(PURPLE, 60), withAlpha(PURPLE, 0)}));
		g.fill(new Ellipse2D.Float(-r, -r, r * 2, r * 2));
	}

	private void drawRays(Graphics2D g, float t, boolean mega)
	{
		int rays = mega ? 18 : 12;
		float len = mega ? 360 : 300;
		double spin = t / 2600.0;
		for (int i = 0; i < rays; i++)
		{
			double a = spin + i * Math.PI * 2 / rays;
			double w = 0.09;
			GeneralPath ray = new GeneralPath();
			ray.moveTo(0, 0);
			ray.lineTo((float) (Math.cos(a - w) * len), (float) (Math.sin(a - w) * len));
			ray.lineTo((float) (Math.cos(a + w) * len), (float) (Math.sin(a + w) * len));
			ray.closePath();
			g.setPaint(new RadialGradientPaint(0, 0, len, new float[]{0f, 1f},
				new Color[]{withAlpha(GOLD, mega ? 120 : 85), withAlpha(GOLD, 0)}));
			g.fill(ray);
		}
	}

	/** A pulsing purple and gold glow hugging the window's edge, with a light chasing round it. */
	private void drawEdgeFlash(Graphics2D g, float t, float pulse, boolean mega)
	{
		Color edge = lerp(GOLD, PURPLE, pulse);
		Rectangle r = new Rectangle(-W / 2, -H / 2, W, H);
		for (int i = 8; i >= 1; i--)
		{
			g.setStroke(new BasicStroke(i * 3.5f));
			g.setColor(withAlpha(edge, 14 + (8 - i) * (mega ? 12 : 9)));
			g.draw(r);
		}

		// A bright spark travelling round the border.
		float perimeter = 2f * (W + H);
		for (int k = 0; k < (mega ? 3 : 2); k++)
		{
			float d = ((t / 3.2f) + k * perimeter / (mega ? 3 : 2)) % perimeter;
			float x;
			float y;
			if (d < W)
			{
				x = -W / 2f + d;
				y = -H / 2f;
			}
			else if (d < W + H)
			{
				x = W / 2f;
				y = -H / 2f + (d - W);
			}
			else if (d < 2 * W + H)
			{
				x = W / 2f - (d - W - H);
				y = H / 2f;
			}
			else
			{
				x = -W / 2f;
				y = H / 2f - (d - 2 * W - H);
			}
			g.setPaint(new RadialGradientPaint(x, y, 26, new float[]{0f, 1f},
				new Color[]{new Color(255, 255, 255, 230), new Color(255, 220, 120, 0)}));
			g.fill(new Ellipse2D.Float(x - 26, y - 26, 52, 52));
		}
	}

	private void drawSparkles(Graphics2D g, Popup p, float t)
	{
		for (float[] s : p.sparkles)
		{
			float a = (float) Math.sin(t * s[3] + s[2]);
			if (a <= 0)
			{
				continue;
			}
			a = a * a * a;
			float size = s[4] * (0.6f + 0.4f * a);
			g.setColor(withAlpha(a > 0.6f ? Color.WHITE : GOLD, (int) (230 * a)));
			g.fill(star(s[0], s[1], size));
		}
	}

	private void drawHeader(Graphics2D g, Popup p, float t)
	{
		String text;
		switch (p.headline.getTier())
		{
			case MEGA:
				text = "MEGA RARE!";
				break;
			case PET:
				text = "PET!";
				break;
			case SCROLL:
				text = "PURPLE..?";
				break;
			default:
				text = "PURPLE!";
		}
		g.setFont(FontManager.getRunescapeBoldFont().deriveFont(32f));
		FontMetrics fm = g.getFontMetrics();
		float x = -fm.stringWidth(text) / 2f;
		float baseY = -H / 2f - 18;
		for (int i = 0; i < text.length(); i++)
		{
			String c = String.valueOf(text.charAt(i));
			float y = baseY + (float) Math.sin(t / 130.0 + i * 0.55) * 3.5f;
			g.setColor(new Color(40, 0, 50, 220));
			g.drawString(c, x + 2, y + 2);
			g.setPaint(new GradientPaint(0, y - 24, new Color(255, 245, 190), 0, y, GOLD));
			g.drawString(c, x, y);
			x += fm.stringWidth(c);
		}
	}

	/** The joke, typed out under the window. */
	private void drawQuip(Graphics2D g, Popup p, float t)
	{
		float y = H / 2f + 24;
		if (t > QUIP_START_MS)
		{
			int chars = Math.min(p.quip.length(), (int) ((t - QUIP_START_MS) / QUIP_MS_PER_CHAR));
			g.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics fm = g.getFontMetrics();
			for (String line : wrap(p.quip.substring(0, chars), fm, W + 80))
			{
				centered(g, line, 0, y, Color.WHITE);
				y += fm.getHeight();
			}
		}
		if (p.footer != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g.getFontMetrics();
			String footer = p.footer;
			while (fm.stringWidth(footer) > W + 80 && footer.length() > 4)
			{
				footer = footer.substring(0, footer.length() - 4) + "..";
			}
			centered(g, footer, 0, H / 2f + 62, new Color(200, 180, 220));
		}
	}

	// ---- Helpers ----

	private BufferedImage sprite(int id)
	{
		return spriteManager.getSprite(id, 0);
	}

	private static void centered(Graphics2D g, String s, float cx, float y, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		float x = cx - fm.stringWidth(s) / 2f;
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(color);
		g.drawString(s, x, y);
	}

	private static List<String> wrap(String text, FontMetrics fm, int width)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" ", -1))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(next) > width && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	private static Shape star(float x, float y, float r)
	{
		float in = r * 0.28f;
		GeneralPath s = new GeneralPath();
		s.moveTo(x, y - r);
		s.lineTo(x + in, y - in);
		s.lineTo(x + r, y);
		s.lineTo(x + in, y + in);
		s.lineTo(x, y + r);
		s.lineTo(x - in, y + in);
		s.lineTo(x - r, y);
		s.lineTo(x - in, y - in);
		s.closePath();
		return s;
	}

	private static float clamp(float v)
	{
		return Math.max(0f, Math.min(1f, v));
	}

	private static float easeOutBack(float x)
	{
		float c1 = 1.9f;
		float c3 = c1 + 1;
		return (float) (1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2));
	}

	private static Color withAlpha(Color c, int a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, a)));
	}

	private static Color lerp(Color a, Color b, float f)
	{
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * f),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * f),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * f));
	}
}

