package com.chambersfomo;

/**
 * The fake "Regret" skill. It uses the same XP table as a real skill: level 99
 * at 13,034,431 XP, with XP going on to 200M.
 *
 * Rates are tuned like Agility: slow at level 1 and climbing as you level, the way
 * better courses unlock, until they top out around 55k XP/hr in the 90s:
 * <ul>
 * <li>At the top, each reroll gives {@link #BASE_XP}, plus 1 XP per {@link #GP_PER_BONUS_XP} gp
 * the layout would have given you. The bonus caps at {@link #MAX_COMMON_BONUS_XP} for common
 * loot, so a normal reroll is at most 410 XP, and at {@link #MAX_PURPLE_BONUS_XP} with a purple.</li>
 * <li>Below the top, all of that is scaled down by {@link #rateMultiplier(int)}.</li>
 * <li>A reroll faster than {@link #FULL_XP_SECONDS} seconds after the last one gives
 * proportionally less, so spamming can't beat about 133 rerolls' worth an hour
 * (about 55k XP/hr). Purples and the pet are rare spikes on top, like a lucky lap.</li>
 * </ul>
 */
final class RegretSkill
{
	static final String NAME = "Regret";
	static final int MAX_LEVEL = 99;
	static final long MAX_XP = 200_000_000L;

	static final int BASE_XP = 250;
	static final int GP_PER_BONUS_XP = 2_500;
	static final int MAX_COMMON_BONUS_XP = 160;
	static final int MAX_PURPLE_BONUS_XP = 1_000;
	/** Untradeable pets have no price, so they give a flat bonus instead. */
	static final int PET_BONUS_XP = 1_000;
	static final int FULL_XP_SECONDS = 27;

	/** The XP/hr ceiling at the top, which every level's rate is a share of. */
	static final int TOP_XP_PER_HOUR = 55_000;

	/**
	 * Max XP/hr by level, like moving up Agility courses: {level, XP/hr} points,
	 * with straight lines between them.
	 */
	private static final int[][] RATE_BY_LEVEL = {
		{1, 6_000},
		{10, 9_000},
		{20, 13_000},
		{30, 18_000},
		{40, 24_000},
		{50, 31_000},
		{60, 38_000},
		{70, 44_000},
		{80, 49_000},
		{90, 55_000},
		{99, 55_000},
	};

	/** XP needed for each level; index 1 is level 1. */
	private static final long[] XP_FOR_LEVEL = new long[MAX_LEVEL + 1];

	static
	{
		double points = 0;
		for (int level = 1; level <= MAX_LEVEL; level++)
		{
			XP_FOR_LEVEL[level] = (long) Math.floor(points / 4);
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
		}
	}

	private RegretSkill()
	{
	}

	/**
	 * XP for one reroll.
	 *
	 * @param level your Regret level before this reroll
	 * @param gpValue what the layout's loot is worth
	 * @param purple whether it had a purple (or pet, dust or kit)
	 * @param pet whether it had an Olmlet
	 * @param secondsSinceLast seconds since the previous reroll; a negative value means
	 * there was none this session, which gives full XP
	 */
	static long xpForRoll(int level, long gpValue, boolean purple, boolean pet, double secondsSinceLast)
	{
		int cap = purple ? MAX_PURPLE_BONUS_XP : MAX_COMMON_BONUS_XP;
		double xp = BASE_XP + Math.min(cap, Math.max(0, gpValue) / GP_PER_BONUS_XP) + (pet ? PET_BONUS_XP : 0);
		xp *= rateMultiplier(level);
		if (secondsSinceLast >= 0 && secondsSinceLast < FULL_XP_SECONDS)
		{
			xp = xp * secondsSinceLast / FULL_XP_SECONDS;
		}
		return Math.max(1, Math.round(xp));
	}

	/** The max XP/hr at a level. */
	static int maxXpPerHour(int level)
	{
		int l = Math.max(1, Math.min(MAX_LEVEL, level));
		for (int i = 1; i < RATE_BY_LEVEL.length; i++)
		{
			int[] lo = RATE_BY_LEVEL[i - 1];
			int[] hi = RATE_BY_LEVEL[i];
			if (l <= hi[0])
			{
				return lo[1] + (hi[1] - lo[1]) * (l - lo[0]) / (hi[0] - lo[0]);
			}
		}
		return TOP_XP_PER_HOUR;
	}

	/** This level's share of the top rate, from about 0.11 at level 1 to 1 in the 90s. */
	static double rateMultiplier(int level)
	{
		return maxXpPerHour(level) / (double) TOP_XP_PER_HOUR;
	}

	static int levelFor(long xp)
	{
		for (int level = MAX_LEVEL; level > 1; level--)
		{
			if (xp >= XP_FOR_LEVEL[level])
			{
				return level;
			}
		}
		return 1;
	}

	static long xpForLevel(int level)
	{
		return XP_FOR_LEVEL[Math.max(1, Math.min(MAX_LEVEL, level))];
	}
}

package com.chambersfomo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

/** Fake XP drops for the Regret skill, floating up by the XP orb like real ones. */
@Singleton
class XpDropOverlay extends Overlay
{
	private static final int LIFE_MS = 2200;
	private static final int RISE_PX = 70;
	/** Drops that arrive close together stack below each other. */
	private static final int STACK_PX = 18;

	private final Client client;
	private final List<long[]> drops = new ArrayList<>();
	private BufferedImage icon;

	@Inject
	XpDropOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void setIcon(BufferedImage icon)
	{
		this.icon = icon;
	}

	synchronized void drop(long xp)
	{
		drops.add(new long[]{System.currentTimeMillis(), xp});
	}

	synchronized void clear()
	{
		drops.clear();
	}

	@Override
	public synchronized Dimension render(Graphics2D g)
	{
		long now = System.currentTimeMillis();
		Iterator<long[]> it = drops.iterator();
		while (it.hasNext())
		{
			if (now - it.next()[0] > LIFE_MS)
			{
				it.remove();
			}
		}
		if (drops.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int right = client.getViewportXOffset() + client.getViewportWidth() - 140;
		int startY = client.getViewportYOffset() + 110;

		for (int i = 0; i < drops.size(); i++)
		{
			long[] drop = drops.get(i);
			float t = (now - drop[0]) / (float) LIFE_MS;
			int y = startY + i * STACK_PX - (int) (t * RISE_PX);
			float alpha = t < 0.75f ? 1f : (1f - t) / 0.25f;
			String text = "+" + QuantityFormatter.formatNumber(drop[1]);
			int x = right - fm.stringWidth(text);

			if (icon != null)
			{
				g.drawImage(icon, x - icon.getWidth() - 3, y - icon.getHeight() + 2, null);
			}
			g.setColor(new Color(0, 0, 0, (int) (255 * alpha)));
			g.drawString(text, x + 1, y + 1);
			g.setColor(new Color(235, 200, 255, (int) (255 * alpha)));
			g.drawString(text, x, y);
		}
		return null;
	}
}

