package com.chambersfomo;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

public class LootSimulatorTest
{
	@Test
	public void tableWeightsAddUp()
	{
		int normal = 0;
		int cm = 0;
		for (Loot loot : Loot.values())
		{
			normal += loot.getWeight();
			cm += loot.getWeightCm();
		}
		assertEquals(Loot.TABLE_TOTAL, normal);
		assertEquals(Loot.TABLE_TOTAL_CM, cm);
		assertEquals(60, normal);
		assertEquals(56, cm);
	}

	@Test
	public void commonTableHas33Items()
	{
		int onTable = 0;
		for (CommonLoot loot : CommonLoot.values())
		{
			if (loot.onTable())
			{
				onTable++;
			}
		}
		assertEquals(CommonLoot.TABLE_SIZE, onTable);
	}

	@Test
	public void uniqueChanceMatchesPublishedRate()
	{
		assertEquals(0.01, LootSimulator.uniqueChance(8676), 1e-9);
		// Capped at 570,000 points, which is 65.7%.
		assertEquals(0.657, LootSimulator.uniqueChance(10_000_000), 0.001);
	}

	@Test
	public void soloRaidHitsAtTheExpectedRate()
	{
		LootSimulator sim = new LootSimulator(new Random(1));
		int raids = 200_000;
		int hits = 0;
		for (int i = 0; i < raids; i++)
		{
			LootSimulator.RaidLoot loot = sim.roll(30_000, 0, false);
			if (loot.uniques.stream().anyMatch(l -> l.getWeight() > 0))
			{
				hits++;
			}
		}
		double expected = 30_000 / 867_600.0;
		assertEquals(expected, hits / (double) raids, 0.002);
		assertEquals(expected, LootSimulator.chanceOfYourPurple(30_000, 0), 1e-9);
	}

	@Test
	public void teamShareLowersYourOdds()
	{
		// A third of the points in a 90k team raid is the same as 30k solo for the first roll.
		assertEquals(LootSimulator.chanceOfYourPurple(30_000, 0),
			LootSimulator.chanceOfYourPurple(30_000, 90_000), 1e-9);
		// Same team, smaller share: worse odds.
		assertTrue(LootSimulator.chanceOfYourPurple(10_000, 90_000) < LootSimulator.chanceOfYourPurple(30_000, 90_000));
	}

	@Test
	public void tableDistributionFollowsWeights()
	{
		for (boolean cm : new boolean[]{false, true})
		{
			LootSimulator sim = new LootSimulator(new Random(7));
			Map<Loot, Integer> counts = new EnumMap<>(Loot.class);
			int n = 600_000;
			for (int i = 0; i < n; i++)
			{
				counts.merge(sim.rollTable(cm), 1, Integer::sum);
			}
			for (Loot loot : Loot.values())
			{
				double expected = cm ? loot.getWeightCm() / 56.0 : loot.getWeight() / 60.0;
				assertEquals(loot.name(), expected, counts.getOrDefault(loot, 0) / (double) n, 0.003);
			}
		}
	}

	@Test
	public void commonLootIsTwoDifferentItemsOnlyWithoutAPurple()
	{
		LootSimulator sim = new LootSimulator(new Random(3));
		int clues = 0;
		int dry = 0;
		for (int i = 0; i < 50_000; i++)
		{
			LootSimulator.RaidLoot loot = sim.roll(30_000, 0, false);
			if (loot.uniques.isEmpty())
			{
				dry++;
				long tableItems = loot.common.stream().filter(d -> d.item.onTable()).count();
				assertEquals(2, tableItems);
				assertNotEquals(loot.common.get(0).item, loot.common.get(1).item);
				clues += loot.common.size() - 2;
			}
			else
			{
				assertTrue(loot.common.isEmpty());
			}
		}
		assertEquals(1 / 12.0, clues / (double) dry, 0.006);
	}

	@Test
	public void commonQuantityScalesWithPoints()
	{
		// 131,071 / 3,640 = 36 points per death rune.
		assertEquals(833, CommonLoot.DEATH_RUNE.quantity(30_000));
		assertEquals(3640, CommonLoot.DEATH_RUNE.quantity(131_071));
		assertEquals(3640, CommonLoot.DEATH_RUNE.quantity(500_000));
		assertEquals(1, CommonLoot.RUNITE_ORE.quantity(100));
		assertEquals(1, CommonLoot.DARK_RELIC.quantity(30_000));
		assertEquals(65535, CommonLoot.PURE_ESSENCE.quantity(131_071));
	}
}

package com.chambersfomo;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RegretSkillTest
{
	@Test
	public void usesTheRealXpCurve()
	{
		assertEquals(0, RegretSkill.xpForLevel(1));
		assertEquals(83, RegretSkill.xpForLevel(2));
		assertEquals(6_517_253, RegretSkill.xpForLevel(92));
		assertEquals(13_034_431, RegretSkill.xpForLevel(99));
	}

	@Test
	public void levelsFromXp()
	{
		assertEquals(1, RegretSkill.levelFor(0));
		assertEquals(1, RegretSkill.levelFor(82));
		assertEquals(2, RegretSkill.levelFor(83));
		assertEquals(98, RegretSkill.levelFor(13_034_430));
		assertEquals(99, RegretSkill.levelFor(13_034_431));
		assertEquals(99, RegretSkill.levelFor(200_000_000));
	}

	@Test
	public void xpForARollAtTheTop()
	{
		assertEquals(250, RegretSkill.xpForRoll(99, 0, false, false, -1));
		assertEquals(250 + 120, RegretSkill.xpForRoll(99, 300_000, false, false, -1));
		// Common loot bonus caps at 160, purples at 1,000.
		assertEquals(410, RegretSkill.xpForRoll(99, 50_000_000, false, false, -1));
		assertEquals(1_250, RegretSkill.xpForRoll(99, 1_500_000_000, true, false, -1));
		assertEquals(250 + 1_000, RegretSkill.xpForRoll(99, 0, true, true, -1));
		// Twice as fast as the full-XP pace gives half.
		assertEquals(205, RegretSkill.xpForRoll(99, 50_000_000, false, false, 13.5));
	}

	@Test
	public void lowLevelsEarnLess()
	{
		assertEquals(6_000, RegretSkill.maxXpPerHour(1));
		assertEquals(31_000, RegretSkill.maxXpPerHour(50));
		assertEquals(55_000, RegretSkill.maxXpPerHour(90));
		assertEquals(55_000, RegretSkill.maxXpPerHour(99));
		assertEquals(45, RegretSkill.xpForRoll(1, 50_000_000, false, false, -1));
		assertTrue(RegretSkill.xpForRoll(40, 50_000_000, false, false, -1)
			< RegretSkill.xpForRoll(60, 50_000_000, false, false, -1));
	}

	@Test
	public void ratesNeverBeatTheLevelCeiling()
	{
		// Rerolling at different speeds with rich common loot, for an hour.
		for (int level : new int[]{1, 30, 60, 99})
		{
			for (double gap : new double[]{5, 15, 27, 45})
			{
				long xp = 0;
				for (double t = 0; t < 3600; t += gap)
				{
					xp += RegretSkill.xpForRoll(level, 10_000_000, false, false, t == 0 ? -1 : gap);
				}
				assertTrue("level " + level + " gap " + gap + "s gave " + xp,
					xp <= RegretSkill.maxXpPerHour(level) * 1.02);
			}
		}
	}

	@Test
	public void ninetyNineTakesAboutAsLongAsAgility()
	{
		double hours = 0;
		for (int level = 1; level < 99; level++)
		{
			hours += (RegretSkill.xpForLevel(level + 1) - RegretSkill.xpForLevel(level))
				/ (double) RegretSkill.maxXpPerHour(level);
		}
		assertTrue("hours to 99: " + hours, hours > 230 && hours < 280);
	}
}
